# Validate reconstructed CP28 T/NK-interface outputs.
source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R")); rp_install_and_load(c("dplyr","readr","tibble")); source(file.path(sd_repo_root(),"R","panels","CP28","MANIFEST_RECONSTRUCTED.R")); a<-sd_analysis_dir("CP28"); out<-file.path(a,"validation"); dir.create(out,recursive=TRUE,showWarnings=FALSE)
q<-readr::read_csv(file.path(a,"02_feature_extraction","SDY2583_CP28_feature_extraction_summary_STEP2_TNK_interface_RECONSTRUCTED.csv"),show_col_types=FALSE); m<-readr::read_csv(file.path(a,"04_metadata_merge_age_QC","SDY2583_CP28_metadata_age_QC_summary_RECONSTRUCTED.csv"),show_col_types=FALSE); st<-readr::read_csv(file.path(a,"06_statistics_age_sex_adjusted","SDY2583_CP28_age_sex_adjusted_statistics_STEP3B_RECONSTRUCTED.csv"),show_col_types=FALSE); sc<-readr::read_csv(file.path(a,"08_composite_scores","SDY2583_CP28_composite_score_statistics_RECONSTRUCTED.csv"),show_col_types=FALSE); mt<-readr::read_csv(file.path(a,"10_age_sensitivity","SDY2583_CP28_age_matched_sensitivity_summary_RECONSTRUCTED.csv"),show_col_types=FALSE)
near<-function(x,y,t=.02)is.finite(x)&&abs(x-y)<=t*max(1,abs(y)); checks<-tibble::tribble(~check,~observed,~expected,~pass,"files",q$n_files[1],850,q$n_files[1]==850,"success",q$n_success[1],850,q$n_success[1]==850,"median total",q$median_total_events[1],309700.5,near(q$median_total_events[1],309700.5,.001),"median dump-low",q$median_dump_low_events[1],77505,near(q$median_dump_low_events[1],77505,.001),"median CD3 dump-low",q$median_cd3_dump_low_events[1],25096,near(q$median_cd3_dump_low_events[1],25096,.001),"median CD3CD8",q$median_cd3_cd8_events[1],7440,near(q$median_cd3_cd8_events[1],7440,.001),"median CD3negCD56pos",q$median_cd3neg_cd56pos_events[1],3066.5,near(q$median_cd3neg_cd56pos_events[1],3066.5,.001),"valid ages",m$n_valid_age[1],832,m$n_valid_age[1]==832,"module rows",nrow(st),nrow(CP28_MANIFEST$module_map),nrow(st)==nrow(CP28_MANIFEST$module_map),"5y pairs",mt$n_pairs[mt$caliper_years==5][1],265,mt$n_pairs[mt$caliper_years==5][1]==265,"10y pairs",mt$n_pairs[mt$caliper_years==10][1],273,mt$n_pairs[mt$caliper_years==10][1]==273,"integrated beta",sc$beta_cancer_vs_healthy[sc$score==CP28_MANIFEST$integrated_score][1],.257,near(sc$beta_cancer_vs_healthy[sc$score==CP28_MANIFEST$integrated_score][1],.257,.02))
ref<-path.expand(Sys.getenv("SDY2583_CP28_REFERENCE_DIR",unset="")); if(nzchar(ref)&&dir.exists(ref)){pairs<-list(c(file.path(a,"02_feature_extraction","SDY2583_CP28_FULL_850_feature_table_STEP2_TNK_interface_RECONSTRUCTED.csv"),"SDY2583_CP28_FULL_850_feature_table_STEP2_TNK_interface.csv","subject_id"),c(file.path(a,"06_statistics_age_sex_adjusted","SDY2583_CP28_age_sex_adjusted_statistics_STEP3B_RECONSTRUCTED.csv"),"SDY2583_CP28_age_sex_adjusted_statistics_STEP3B.csv","module,feature"),c(file.path(a,"08_composite_scores","SDY2583_CP28_composite_score_statistics_RECONSTRUCTED.csv"),"SDY2583_CP28_composite_score_statistics.csv","score"),c(file.path(a,"12_threshold_sensitivity","SDY2583_CP28_threshold_sensitivity_summary_WIDE_RECONSTRUCTED.csv"),"SDY2583_CP28_threshold_sensitivity_summary_WIDE.csv","feature")); for(p in pairs){hit<-list.files(ref,p[2],full.names=TRUE,recursive=TRUE,fixed=TRUE); cmp<-if(length(hit))rp_compare_csv(p[1],hit[1],strsplit(p[3],",",fixed=TRUE)[[1]])else tibble::tibble(pass=FALSE,detail="reference missing"); checks<-dplyr::bind_rows(checks,tibble::tibble(check=p[2],observed=cmp$detail[1],expected="table match",pass=cmp$pass[1]))}}
readr::write_csv(checks,file.path(out,"SDY2583_CP28_reconstruction_validation_report.csv")); print(checks,n=nrow(checks)); if(any(!checks$pass))stop("CP28 validation failed.")
